
import type { DeliveryFulfillmentDetailsInput } from './DeliveryFulfillmentDetailsInput.js';
import type { DigitalFulfillmentDetailsInput } from './DigitalFulfillmentDetailsInput.js';
import type { FulfillmentLineItemInput } from './FulfillmentLineItemInput.js';
import type { FulfillmentRecipientInput } from './FulfillmentRecipientInput.js';
import type { PickupFulfillmentDetailsInput } from './PickupFulfillmentDetailsInput.js';
import type { ServiceFulfillmentDetailsInput } from './ServiceFulfillmentDetailsInput.js';

export type FulfillmentInput = { /** Current hold details. While this field is present, status continues to show the public work status from before the hold. */ "active_hold"?: never; "charges"?: never; /** Completion evidence timestamp. Format: date-time. */ "completed_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; "customer_id"?: string; "device_id"?: string; "digital_details"?: DigitalFulfillmentDetailsInput; /** First time this fulfillment reached dispatched. Format: date-time. */ "dispatched_at"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; "fulfillment_id"?: never; "line_items": Array<FulfillmentLineItemInput>; "local_delivery_details"?: DeliveryFulfillmentDetailsInput; "location_id"?: string; "metadata"?: Record<string, string>; "order"?: never; "order_id"?: never; /** Terminal outcome details. The mark_no_show action records its reason here and returns status as failed. */ "outcome"?: never; "packages"?: never; /** First time this fulfillment reached packed. Format: date-time. */ "packed_at"?: never; /** First time this fulfillment reached picked. Format: date-time. */ "picked_at"?: never; "pickup_details"?: PickupFulfillmentDetailsInput; /** Read-only current quantity accounting behavior for this fulfillment state. */ "quantity_effect"?: never; "recipient"?: FulfillmentRecipientInput; /** Provider acceptance state, independent from fulfillment work progress. The accept action sets this field to accepted while status remains pending. */ "request_status"?: never; "service_details"?: ServiceFulfillmentDetailsInput; "shipments"?: never; /** Public work status. Fulfillments with request_status accepted project to status pending. Fulfillments with outcome.outcome_type no_show project to status failed. A fulfillment with active_hold projects to its public work status from before the hold. - `pending`: Work has not started. Start, schedule, accept, hold, cancel, or fail it as supported_actions allows. - `in_progress`: Work has started and is not yet ready or complete. - `ready`: The fulfillment is ready for pickup, handoff, or completion. - `completed`: All fulfillment work completed successfully. - `canceled`: The fulfillment was intentionally canceled and will not continue. - `failed`: The fulfillment could not be completed. Resolve the recorded reason before creating replacement work. - `scheduled`: The fulfillment is scheduled for its recorded service window. - `preparing`: Warehouse or provider preparation is underway. - `picked`: The assigned items have been picked. - `packed`: The assigned items have been packed. - `dispatched`: The fulfillment left its origin for delivery or handoff. */ "status"?: never; /** Read-only actions currently supported for this fulfillment. */ "supported_actions"?: never; /** When the fulfillment entered a terminal state: completed, canceled, or failed. This records the state transition; completed_at records completion evidence supplied for the fulfillment. Format: date-time. */ "terminal_at"?: never; "type": "shipment" | "pickup" | "local_delivery" | "digital" | "service"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; /** Monotonic fulfillment version for expected_version checks. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version"?: never; };
